        {
            accepted = accepted + 1;
        }
        else
        {
            duplicates = duplicates + 1;
        }
    }
    string status = "review";
    if (rows.Count == 0)
    {
        status = "empty";
    }
    else if (accepted == rows.Count)
    {
        status = "clean";
    }
    return new AuditReport(status, accepted, duplicates, invalid);
}

